module Road
  OBSTACLE = :obstacle

  class Segment
    attr_reader :id, :from, :to, :length, :lanes, :limit, :cells, :counts, :turns
    attr_accessor :junction, :stop

    def initialize(id, from, to, length, lanes, limit)
      @id, @from, @to = id, from, to
      @length, @lanes, @limit = length, lanes, limit
      @cells = Array.new(lanes + 1) { |lane| lane.zero? ? nil : Array.new(length) }
      @counts = Hash.new(0)
      @turns = []
      @junction = nil
      @stop = nil
    end

    def free(lane, cell, cap)
      count = 0
      while count < cap && cell + count + 1 < @length && @cells[lane][cell + count + 1].nil?
        count += 1
      end
      count
    end

    def first(lane)
      @cells[lane].index { |cell| !cell.nil? } || @length
    end

    def safe?(lane, cell)
      ([0, cell - @limit].max..cell).all? { |position| @cells[lane][position].nil? }
    end

    def vehicles(reverse: false)
      result = []
      1.upto(@lanes) do |lane|
        row = reverse ? @cells[lane].reverse_each : @cells[lane].each
        row.each { |cell| result << cell unless cell.nil? || cell == OBSTACLE }
      end
      result
    end

    def picture(lane)
      @cells[lane].map do |cell|
        cell.nil? ? '.' : cell == OBSTACLE ? '#' : cell.speed.to_s
      end.join
    end
  end

  class Incident
    attr_reader :segment, :lane, :cell, :start, :finish, :active_start, :active_end

    def initialize(segment, lane, cell, start, finish)
      @segment, @lane, @cell = segment, lane, cell
      @start, @finish = start, finish
      @state = :planned
      @active_start = nil
      @active_end = nil
    end

    def update(step)
      event = nil
      if @state == :active && step > @finish
        @state = :cleared
        @segment.cells[@lane][@cell] = nil
        event = 'INCIDENT_END'
      elsif @state == :planned && step > @finish
        @state = :cancelled
      elsif @state == :planned && step >= @start && @segment.cells[@lane][@cell].nil?
        @state = :active
        @segment.cells[@lane][@cell] = OBSTACLE
        @active_start = step
        event = 'INCIDENT_START'
      end
      @active_end = step if @state == :active
      event
    end
  end
end

module Vehicles
  ClassInfo = Struct.new(:name, :vmax, :weight, :overtake, :stop, keyword_init: true)

  class Vehicle
    attr_reader :number, :kind, :source, :arrival, :route, :completed_stops
    attr_accessor :insertion, :exit, :sink, :segment, :lane, :cell, :speed, :turn,
                  :network_steps, :distance, :stopped_steps, :stop_count, :lane_changes, :dwell

    def initialize(number, kind, source, arrival)
      @number, @kind, @source, @arrival = number, kind, source, arrival
      @insertion = @exit = @sink = nil
      @segment = @lane = @cell = @turn = nil
      @speed = 0
      @route = []
      @completed_stops = {}
      @network_steps = @distance = @stopped_steps = @stop_count = @lane_changes = @dwell = 0
    end

    def maximum
      [@kind.vmax, @segment.limit].min
    end

    def place(segment, lane, cell)
      @segment.cells[@lane][@cell] = nil if @segment
      @segment, @lane, @cell = segment, lane, cell
      segment.cells[lane][cell] = self
    end

    def leave
      @segment.cells[@lane][@cell] = nil
      @segment = @lane = @cell = nil
    end

    def heading_for_stop?
      @kind.stop == 'Y' && @segment && @segment.stop &&
        !@completed_stops[@segment.id] && @cell <= @segment.stop.cell
    end
  end

  def self.slowdown(speed, previous, moving_probability, stopped_probability, generator)
    random = generator.draw
    probability = previous.zero? ? stopped_probability : moving_probability
    speed > 0 && random % 1000 < probability ? speed - 1 : speed
  end
end
